import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';
import { roundCents } from './money.js';
import { isValidDate, addDays, endOfMonth } from './dates.js';

function isValidDiscount(discountPercent) {
  return typeof discountPercent === 'number' && discountPercent >= 0 && discountPercent <= 100;
}

function calculateDueDate(issueDate, terms) {
  switch (terms) {
    case 'NET14':
      return addDays(issueDate, 14);
    case 'NET30':
      return addDays(issueDate, 30);
    case 'EOM':
      return endOfMonth(issueDate);
    default:
      return null;
  }
}

/**
 * Calculate the total for a single line (qty * unitPrice).
 * @param {{ qty: number, unitPrice: number }}
 * @returns {number}
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate the discount for a single line.
 * @param {{ qty: number, unitPrice: number, discountPercent?: number }}
 * @returns {number}
 */
function lineDiscount(line) {
  const discount = lineTotal(line) * (line.discountPercent ?? 0) / 100;
  return Math.max(0, roundCents(discount));
}

/**
 * Calculate the VAT for a single line.
 * @param {{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }}
 * @returns {number}
 */
function lineVat(line) {
  const amountAfterDiscount = lineTotal(line) - lineDiscount(line);
  const vat = amountAfterDiscount * (line.vatRate ?? 0) / 100;
  return Math.max(0, roundCents(vat));
}

/**
 * Calculate subtotal, discount, VAT, voucher, and total for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }>, voucher?: { code: string, amount: number } }}
 * @returns {{ subtotal: number, discount: number, vat: number, voucher: number, total: number }}
 */
export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
  const discount = invoice.lines.reduce((sum, line) => sum + lineDiscount(line), 0);
  const vat = invoice.lines.reduce((sum, line) => sum + lineVat(line), 0);
  const voucher = invoice.voucher ? invoice.voucher.amount : 0;
  const total = Math.max(0, subtotal - discount + vat - voucher);
  return { subtotal, discount, vat, voucher, total };
}

/**
 * Create a draft invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }>, terms?: string }}
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array, terms: string, dueDate: string } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines, terms = 'NET30' }) {
  const normalizedCustomerId = normalizeId(customerId);
  const customer = getCustomer(normalizedCustomerId);
  if (!customer.ok) return customer;

  if (!isValidDate(issueDate)) {
    return fail('DATE_INVALID');
  }

  const dueDate = calculateDueDate(issueDate, terms);
  if (dueDate === null) {
    return fail('TERMS_INVALID');
  }

  if (!Array.isArray(lines) || lines.length === 0) {
    return fail('NO_LINES');
  }

  const invoiceLines = [];
  for (const line of lines) {
    if (!Number.isInteger(line.qty) || line.qty <= 0) {
      return fail('QTY_INVALID');
    }

    const discountPercent = 'discountPercent' in line ? line.discountPercent : TIER_DISCOUNTS[customer.value.tier];
    if (!isValidDiscount(discountPercent)) {
      return fail('DISCOUNT_INVALID');
    }

    const product = getProduct(line.sku);
    if (!product.ok) return product;

    invoiceLines.push({
      sku: line.sku,
      name: product.value.name,
      qty: line.qty,
      unitPrice: product.value.unitPrice,
      vatRate: product.value.vatRate,
      discountPercent,
    });
  }

  return ok({
    customerId: normalizedCustomerId,
    issueDate,
    status: 'draft',
    lines: invoiceLines,
    terms,
    dueDate,
  });
}

/**
 * Add a line to an invoice or increase its quantity if it already exists.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} param
 */
export function addLine(invoice, param) {
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  if (!Number.isInteger(param.qty) || param.qty <= 0) {
    return fail('QTY_INVALID');
  }

  const customer = getCustomer(invoice.customerId);
  if (!customer.ok) return customer;

  const discount = 'discountPercent' in param ? param.discountPercent : TIER_DISCOUNTS[customer.value.tier];
  if (!isValidDiscount(discount)) {
    return fail('DISCOUNT_INVALID');
  }

  const product = getProduct(param.sku);
  if (!product.ok) return product;

  const newLines = invoice.lines.map((line) => ({ ...line }));
  const existingLineIndex = newLines.findIndex((line) => line.sku === param.sku);

  if (existingLineIndex >= 0) {
    newLines[existingLineIndex].qty += param.qty;
  } else {
    newLines.push({
      sku: param.sku,
      name: product.value.name,
      qty: param.qty,
      unitPrice: product.value.unitPrice,
      vatRate: product.value.vatRate,
      discountPercent: discount,
    });
  }

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: invoice.status,
    lines: newLines,
    terms: invoice.terms,
    dueDate: invoice.dueDate,
    ...(invoice.voucher && { voucher: invoice.voucher }),
  });
}

/**
 * Remove a line from an invoice.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
 * @param {string} sku
 */
export function removeLine(invoice, sku) {
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex < 0) {
    return fail('LINE_NOT_FOUND');
  }

  if (invoice.lines.length === 1) {
    return fail('NO_LINES');
  }

  const newLines = invoice.lines.filter((_, i) => i !== lineIndex);

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: invoice.status,
    lines: newLines,
    terms: invoice.terms,
    dueDate: invoice.dueDate,
    ...(invoice.voucher && { voucher: invoice.voucher }),
  });
}

/**
 * Issue an invoice (change status from draft to issued and assign a number).
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
 * @param {Array<string>} existingNumbers - Invoice numbers already used
 */
export function issueInvoice(invoice, existingNumbers) {
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    number,
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: 'issued',
    lines: invoice.lines.map((line) => ({ ...line })),
    terms: invoice.terms,
    dueDate: invoice.dueDate,
    ...(invoice.voucher && { voucher: invoice.voucher }),
  });
}

/**
 * Apply a voucher to a draft invoice.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array, voucher?: { code: string, amount: number } }} invoice
 * @param {{ code: string, amount: number }} param
 */
export function applyVoucher(invoice, { code, amount }) {
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  if (invoice.voucher) {
    return fail('VOUCHER_EXISTS');
  }

  if (!Number.isInteger(amount) || amount <= 0) {
    return fail('AMOUNT_INVALID');
  }

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: invoice.status,
    lines: invoice.lines.map((line) => ({ ...line })),
    terms: invoice.terms,
    dueDate: invoice.dueDate,
    voucher: { code, amount },
  });
}

